import { MeshBasicNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import {} from '@/primitives';
import {} from '@/text';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  const root = new Group();

  // Geometry based on image aspect (512 / 320 = 1.6)
  const aspect = 1.6;
  const geometry = new PlaneGeometry(aspect, 1);
  const material = new MeshBasicNodeMaterial({
    color: 0xffffff,
    transparent: true,
  });

  const plane = new Mesh(geometry, material);
  root.add(plane);

  // Load texture asynchronously; apply when ready
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      material.map = tex;
      material.needsUpdate = true;
    });
  }

  // Create text objects from config
  const items =
    config.textContent ??
    config.intent?.visualSpec?.textContent ??
    [];

  for (const item of items) {
    const txt = ctx.fontAtlas.createText(item.text ?? '', {
      fontSize: item.typography?.fontSize ?? 39,
      color: (config.colors?.paper ||
        config.intent?.visualSpec?.colors?.paper ||
        '#e8ecf2'),
      align: 'center',
    });
    // Centered on plane by default
    root.add(txt);
  }

  // Handlers placeholder (no interactions defined)
  root.userData.handlers = {};

  // Cleanup resources
  root.userData.cleanup = () => {
    // Dispose texture if loaded
    if (material.map) {
      material.map.dispose();
    }
    material.dispose();
    geometry.dispose();

    // Kill any GSAP timelines (none in this node, but safeguard)
    gsap.globalTimeline.clear();
  };

  return root;
}
